#!/usr/bin/env python3
"""
LOO-CAST ADVANCED CLEANUP MEGA-ULTRA PATCH V5

Self-contained dependency-ordered cleanup installer.

V5 repairs guarded matchers and incomplete migrations found by an isolated
46-stage replay. It also routes remaining runtime flight actuator changes
through FlightControlRequest, and keeps issue sync opt-in.

V4 repairs the stage-03 HUD structural guard exposed while exercising V3:
- the player tuple destructure is scoped to the `player.into_inner()` statement
  instead of the whole `update_context_actions` function;
- the following `context_action_text(...)` call has its own structural region;
- nested structural diagnostics no longer duplicate the same label.

V3 repairs two installer defects discovered while exercising V2:
- the movement capability split now matches HUD structure by named function
  regions and eagerly reports independent structural mismatches before writes;
- the USF/macro cleanup no longer references an undefined FILES variable.

The wrapper also validates every embedded stage before touching the repository.
Stages with independent PATCHES maps plan all file transformations first, so a
stale matcher in one file does not hide failures in other files from the same
stage. Intermediate cargo checks remain deferred; final formatting/check stages
remain authoritative.

Default behavior:
- refuses staged or tracked dirty work; unrelated untracked files remain untouched;
- embeds every stage; no sibling installer files are required;
- uses temporary checkpoint commits so each stage's clean-tree structural guards work;
- defers intermediate `cargo check` failures while preserving structural guards;
- runs real final formatting, boundary validation and compiler checks;
- always collapses temporary commits back to the original HEAD, leaving ONE
  combined uncommitted diff on success OR final validation failure;
- skips GitHub issue synchronization unless --sync-issues is supplied.
"""
from __future__ import annotations

import argparse
import ast
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

