                                            '        c.append(Path(os.environ["LOO_CAST_REPO"]).expanduser())\n'
                                            '    cwd=Path.cwd().resolve()\n'
                                            '    c += '
                                            '[cwd,*cwd.parents,Path.home()/"Vapor"/"Loo-Cast",Path.home()/"Loo-Cast"]\n'
                                            '    for q in c:\n'
                                            '        if (q/".git").exists() and '
