                                            '\n'
                                            '        leftovers=[]\n'
                                            '        for q in rust_files(repo):\n'
                                            '            t=q.read_text()\n'
                                            '            for bad in '
                                            '("UsfPresentationProbe","UsfLocalScalePresentation::new("):\n'
                                            '                if bad in t:\n'
                                            '                    leftovers.append(f"{q.relative_to(repo)}: {bad}")\n'
                                            '        if leftovers:\n'
                                            '            raise RuntimeError("view cleanup '
                                            'incomplete:\\n"+"\\n".join(leftovers))\n'
                                            '\n'
                                            '        rust=[str(repo/r) for r in touched if r.endswith(".rs")]\n'
