                                            '        if f.returncode:\n'
                                            '            raise RuntimeError("rustfmt failed:\\n"+f.stdout+f.stderr)\n'
                                            '        d=run(["git","diff","--check","--",*touched],repo,check=False)\n'
                                            '        if d.returncode:\n'
                                            '            raise RuntimeError("diff-check '
                                            'failed:\\n"+d.stdout+d.stderr)\n'
                                            '        '
                                            'c=run(["cargo","check","-p","spacetime-engine"],repo,check=False)\n'
                                            '        if c.returncode:\n'
                                            '            raise RuntimeError("cargo check '
                                            'failed:\\n"+c.stdout+c.stderr)\n'
                                            '    except Exception:\n'
                                            '        for r,t in original.items():\n'
                                            '            (repo/r).write_text(t)\n'
                                            '        raise\n'
                                            '\n'
                                            '    print("Spatial view/presentation cleanup applied.")\n'
                                            '    print("Presentation probe names its diagnostic-domain role '
                                            'explicitly.")\n'
                                            '    print("Ambiguous local-presentation compatibility constructor '
                                            'removed.")\n'
                                            '    print("Semantic/runtime presentation-origin contract is preserved.")\n'
                                            '    print("Issue-number breadcrumb removed from source.")\n'
                                            '    print("Validation passed.")\n'
                                            '\n'
                                            'if __name__=="__main__":\n'
                                            '    try: main()\n'
                                            '    except Exception as e:\n'
                                            '        print("FAILED SAFELY:",e,file=sys.stderr); sys.exit(1)\n',
