                                           '\n'
                                           'def rust_files(repo):\n'
                                           '    return list((repo/"spacetime-engine/src").rglob("*.rs"))\n'
                                           '\n'
                                           'def callers(repo):\n'
                                           '    out=set()\n'
                                           '    for q in rust_files(repo):\n'
                                           '        t=q.read_text()\n'
                                           '        if any(x in t for x in (\n'
                                           '            "UsfCollisionCandidateRecord",\n'
                                           '            ".push_candidate(",\n'
                                           '            "UsfCollisionQueryFrame",\n'
                                           '        )):\n'
                                           '            out.add(q.relative_to(repo).as_posix())\n'
                                           '    return sorted(out)\n'
                                           '\n'
                                           'def patch_frame(s):\n'
                                           '    '
                                           's=s.replace("UsfCollisionCandidateRecord","UsfCollisionCandidateObservation")\n'
                                           '    s=s.replace("pub fn push_candidate(","pub fn publish_candidate(",1)\n'
                                           '    s=s.replace(\n'
                                           '        "pub(super) fn begin_frame(&mut self)",\n'
                                           '        "pub(super) fn begin_transaction(&mut self)",\n'
                                           '        1\n'
                                           '    )\n'
                                           '    s=s.replace(\n'
                                           '        "pub(super) fn push_request(&mut self",\n'
                                           '        "pub(super) fn submit_request(&mut self",\n'
                                           '        1\n'
                                           '    )\n'
                                           '    s=s.replace(\n'
                                           '        "pub(super) fn finalize(&mut self)",\n'
                                           '        "pub(super) fn finalize_transaction(&mut self)",\n'
                                           '        1\n'
                                           '    )\n'
                                           '    return s\n'
                                           '\n'
                                           'def patch_runtime(s):\n'
                                           '    s=s.replace("frame.begin_frame();","frame.begin_transaction();")\n'
                                           '    s=s.replace("frame.push_request(","frame.submit_request(")\n'
                                           '    s=s.replace("frame.finalize();","frame.finalize_transaction();")\n'
                                           '    return s\n'
                                           '\n'
                                           'def patch_topology(s):\n'
                                           "    old='''//! Runtime collision-space modification.\n"
                                           '//!\n'
                                           '//! Higher-level mechanics publish [`CollisionStencil`] components. Hosts '
                                           'keep\n'
                                           '//! immutable [`CollisionClipSource`] geometry. This module rebuilds the '
                                           'actual\n'
                                           '//! Avian collider only when the effective stencil set changes.\n'
                                           "'''\n"
