                                                 '(q/"spacetime-engine"/"Cargo.toml").exists():\n'
                                                 '            return q.resolve()\n'
                                                 '    raise RuntimeError("could not find repo")\n'
                                                 '\n'
                                                 'def rust_files(repo):\n'
                                                 '    return list((repo/"spacetime-engine/src").rglob("*.rs"))\n'
                                                 '\n'
                                                 'def replace_word(t,old,new):\n'
