                                                 '        q.write_text(patch_live(q.read_text()))\n'
                                                 '        q=repo/"spacetime-engine/src/voxel/resolution/mod.rs"\n'
                                                 '        q.write_text(patch_resolution_mod(q.read_text()))\n'
                                                 '\n'
                                                 '        leftovers=[]\n'
                                                 '        for q in rust_files(repo):\n'
                                                 '            t=q.read_text()\n'
                                                 '            for old in RENAMES:\n'
                                                 '                if re.search(rf"\\b{re.escape(old)}\\b",t):\n'
                                                 '                    leftovers.append(f"{q.relative_to(repo)}: '
                                                 '{old}")\n'
                                                 '        if leftovers:\n'
                                                 '            raise RuntimeError("resolution live migration '
                                                 'incomplete:\\n"+"\\n".join(leftovers))\n'
                                                 '\n'
                                                 '        rust=[str(repo/r) for r in touched if r.endswith(".rs")]\n'
                                                 '        '
                                                 'f=run(["rustfmt","--edition","2024",*rust],repo,check=False)\n'
                                                 '        if f.returncode:\n'
                                                 '            raise RuntimeError("rustfmt '
