                                        '    "sync_controlled_interaction_scale_affinity": '
                                        '"refresh_controlled_interaction_requirement",\n'
                                        '}\n'
                                        'FIXED = [\n'
                                        '    "spacetime-engine/src/game/control/mod.rs",\n'
                                        '    "spacetime-engine/src/game/control/runtime.rs",\n'
                                        ']\n'
                                        '\n'
                                        'def run(cmd,cwd,check=True):\n'
                                        '    '
                                        'result=subprocess.run(cmd,cwd=cwd,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)\n'
                                        '    if check and result.returncode:\n'
                                        '        raise RuntimeError(f"command failed: {\' '
                                        '\'.join(cmd)}\\n{result.stdout}{result.stderr}")\n'
                                        '    return result\n'
                                        '\n'
                                        'def root():\n'
                                        '    candidates=[]\n'
                                        '    if os.environ.get("LOO_CAST_REPO"):\n'
                                        '        candidates.append(Path(os.environ["LOO_CAST_REPO"]).expanduser())\n'
                                        '    cwd=Path.cwd().resolve()\n'
                                        '    candidates += '
                                        '[cwd,*cwd.parents,Path.home()/"Vapor"/"Loo-Cast",Path.home()/"Loo-Cast"]\n'
                                        '    for path in candidates:\n'
                                        '        if (path/".git").exists() and '
                                        '(path/"spacetime-engine"/"Cargo.toml").exists():\n'
                                        '            return path.resolve()\n'
                                        '    raise RuntimeError("could not find Loo-Cast repo")\n'
                                        '\n'
                                        'def rust_files(repo):\n'
                                        '    return list((repo/"spacetime-engine/src").rglob("*.rs"))\n'
                                        '\n'
                                        'def migrate(text):\n'
                                        '    for old,new in RENAMES.items():\n'
                                        '        text=re.sub(rf"\\b{re.escape(old)}\\b",new,text)\n'
                                        '    # Normalize against the earlier transition-facility tranche.\n'
                                        '    text=text.replace("UsfSpatialTransitionQueue","UsfSpatialTransitions")\n'
                                        '    '
                                        'text=text.replace(".set_interaction_requirement(",".require_interaction(")\n'
                                        '    if "UsfSpatialTransitions" in text:\n'
                                        '        text=text.replace("transitions.request(","transitions.relocate(")\n'
                                        '    return text\n'
                                        '\n'
                                        'def main():\n'
                                        '    repo=root()\n'
                                        '    touched=[]\n'
                                        '    for path in rust_files(repo):\n'
                                        '        text=path.read_text()\n'
                                        '        if any(re.search(rf"\\b{re.escape(old)}\\b",text) for old in '
                                        'RENAMES):\n'
                                        '            touched.append(path.relative_to(repo).as_posix())\n'
                                        '    touched=sorted(set(touched+FIXED))\n'
                                        '    dirty=run(["git","status","--porcelain","--",*touched],repo).stdout\n'
                                        '    if dirty.strip():\n'
                                        '        raise RuntimeError("refusing dirty owned paths:\\n"+dirty)\n'
                                        '    original={rel:(repo/rel).read_text() for rel in touched}\n'
                                        '\n'
                                        '    try:\n'
                                        '        for rel in touched:\n'
                                        '            path=repo/rel\n'
                                        '            path.write_text(migrate(path.read_text()))\n'
                                        '\n'
                                        '        runtime=repo/"spacetime-engine/src/game/control/runtime.rs"\n'
                                        '        text=runtime.read_text().replace(\n'
                                        '            "//! Ordered local-control transfer and focus reconciliation.",\n'
                                        '            "//! Ordered local-control transfer transaction and adapter '
                                        'reconciliation.",\n'
                                        '            1,\n'
                                        '        )\n'
                                        '        runtime.write_text(text)\n'
                                        '\n'
                                        '        leftovers=[]\n'
                                        '        for path in rust_files(repo):\n'
                                        '            text=path.read_text()\n'
                                        '            for old in RENAMES:\n'
                                        '                if re.search(rf"\\b{re.escape(old)}\\b",text):\n'
                                        '                    leftovers.append(f"{path.relative_to(repo)}: {old}")\n'
                                        '        if leftovers:\n'
                                        '            raise RuntimeError("control lifecycle migration '
                                        'incomplete:\\n"+"\\n".join(leftovers))\n'
                                        '\n'
                                        '        rust=[str(repo/rel) for rel in touched if rel.endswith(".rs")]\n'
                                        '        result=run(["rustfmt","--edition","2024",*rust],repo,check=False)\n'
                                        '        if result.returncode:\n'
                                        '            raise RuntimeError("rustfmt '
                                        'failed:\\n"+result.stdout+result.stderr)\n'
                                        '        result=run(["git","diff","--check","--",*touched],repo,check=False)\n'
                                        '        if result.returncode:\n'
                                        '            raise RuntimeError("diff-check '
                                        'failed:\\n"+result.stdout+result.stderr)\n'
                                        '        '
                                        'result=run(["cargo","check","-p","spacetime-engine"],repo,check=False)\n'
                                        '        if result.returncode:\n'
                                        '            raise RuntimeError("cargo check '
                                        'failed:\\n"+result.stdout+result.stderr)\n'
                                        '    except Exception:\n'
                                        '        for rel,text in original.items():\n'
