def run(cmd, cwd=None, check=True, env=None):
    result = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    if check and result.returncode:
        raise RuntimeError(
            f"command failed ({result.returncode}): {' '.join(map(str, cmd))}\n"
            f"{result.stdout}{result.stderr}"
        )
    return result


def repo_root():
    candidates = []
    explicit = os.environ.get("LOO_CAST_REPO")
    if explicit:
        candidates.append(Path(explicit).expanduser())
    cwd = Path.cwd().resolve()
    candidates += [
        cwd,
        *cwd.parents,
        Path.home() / "Vapor" / "Loo-Cast",
        Path.home() / "Loo-Cast",
    ]
    for candidate in candidates:
        if (candidate / ".git").exists() and (candidate / "spacetime-engine" / "Cargo.toml").exists():
            return candidate.resolve()
    raise RuntimeError("could not find Loo-Cast checkout; run inside it or set LOO_CAST_REPO")


def require_clean_tracked_tree(repo):
    if run(["git", "diff", "--quiet"], repo, check=False).returncode:
        raise RuntimeError(
            "tracked working-tree changes exist. Commit/stash them before the mega patch; "
            "this installer refuses to guess ownership."
        )
    if run(["git", "diff", "--cached", "--quiet"], repo, check=False).returncode:
        raise RuntimeError("git index already contains staged changes; commit/unstage them first")


def untracked(repo):
    records = run(["git", "status", "--porcelain", "-z"], repo).stdout.split("\0")
    return {record[3:] for record in records if record.startswith("?? ") and len(record) > 3}


def checkpoint(repo, message, original_untracked):
    run(["git", "add", "-u"], repo)

    created = sorted(untracked(repo) - original_untracked)
    if created:
        run(["git", "add", "--", *created], repo)

    if run(["git", "diff", "--cached", "--quiet"], repo, check=False).returncode == 0:
        print("  no repository diff to checkpoint")
        return

    run(["git", "commit", "-m", f"mega-temp: {message}"], repo)
    short = run(["git", "rev-parse", "--short", "HEAD"], repo).stdout.strip()
    print("  temporary checkpoint", short)


def relaxed_cargo_wrapper(temp, real_cargo):
    directory = temp / "relaxed-bin"
    directory.mkdir()
    wrapper = directory / "cargo"
    wrapper.write_text(
        "#!/usr/bin/env python3\n"
        "import os, sys\n"
        f"REAL={real_cargo!r}\n"
        "args=sys.argv[1:]\n"
        "if args and args[0]=='check':\n"
        "    print('[mega-ultra] deferring intermediate cargo check:', ' '.join(args))\n"
        "    raise SystemExit(0)\n"
        "os.execv(REAL,[REAL,*args])\n"
    )
    wrapper.chmod(0o755)
    return directory


def collapse(repo, base_head):
    current = run(["git", "rev-parse", "HEAD"], repo).stdout.strip()
    if current != base_head:
        run(["git", "reset", "--mixed", base_head], repo)


def _module_defined_names(tree):
    names = set()
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    names.add(target.id)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            names.add(node.target.id)
        elif isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                names.add(alias.asname or alias.name.split('.')[0])
    return names


def validate_embedded_bundle():
    declared = [name for name, *_ in STAGES]
    source_names = list(STAGE_SOURCES)
    errors = []

    missing = [name for name in declared if name not in STAGE_SOURCES]
    extra = [name for name in source_names if name not in set(declared)]
    if missing:
        errors.append("declared stages missing embedded source: " + ", ".join(missing))
    if extra:
        errors.append("embedded sources missing stage metadata: " + ", ".join(extra))

    for name in declared:
        source = STAGE_SOURCES.get(name)
        if source is None:
            continue
        try:
            tree = ast.parse(source, filename=name)
            compile(tree, name, "exec")
        except Exception as error:
            errors.append(f"{name}: embedded Python does not compile: {error}")
            continue

        # Catch the class of late typo that bit V2: module-scope ALL_CAPS names
        # referenced by stage code but never defined/imported. This is purposely
        # narrow to avoid pretending to be a full Python linter.
        defined = _module_defined_names(tree)
        loaded_caps = {
            node.id
            for node in ast.walk(tree)
            if isinstance(node, ast.Name)
            and isinstance(node.ctx, ast.Load)
            and node.id.isupper()
        }
        undefined_caps = sorted(loaded_caps - defined)
        if undefined_caps:
            errors.append(
                f"{name}: undefined module-style constant name(s): "
                + ", ".join(undefined_caps)
            )

    if errors:
        raise RuntimeError(
            f"embedded bundle self-check found {len(errors)} error(s):\n  - "
            + "\n  - ".join(errors)
        )


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--list", action="store_true")
    parser.add_argument("--self-check", action="store_true")
    parser.add_argument("--through", type=int)
    parser.add_argument("--sync-issues", action="store_true")
    parser.add_argument("--leave-checkpoints", action="store_true")
    args = parser.parse_args()

    for index, (name, message, mutates, defer_check) in enumerate(STAGES, 1):
        flags = []
        if mutates:
            flags.append("mutates")
        if defer_check:
            flags.append("intermediate-check-deferred")
        if name == "05_seed_advanced_cleanup_issue_queue.py":
            flags.append("optional")
        print(f"{index:02d}  {message}  [{name}]  {' '.join(flags)}")
    if args.list:
        return

    validate_embedded_bundle()
    if args.self_check:
        print(f"Embedded bundle self-check passed for {len(STAGES)} stages.")
        return

    repo = repo_root()
    require_clean_tracked_tree(repo)
    base_head = run(["git", "rev-parse", "HEAD"], repo).stdout.strip()
    original_untracked = untracked(repo)

    real_cargo = shutil.which("cargo")
    if real_cargo is None:
        raise RuntimeError("cargo is required")

    completed = 0
    failure = None

    with tempfile.TemporaryDirectory(prefix="loo-cast-mega-ultra-") as raw_temp:
        temp = Path(raw_temp)
        stage_dir = temp / "stages"
        stage_dir.mkdir()

        for name, source in STAGE_SOURCES.items():
            path = stage_dir / name
            path.write_text(source)
            path.chmod(0o755)

        relaxed_bin = relaxed_cargo_wrapper(temp, real_cargo)
        normal_env = os.environ.copy()
        relaxed_env = normal_env.copy()
        relaxed_env["PATH"] = str(relaxed_bin) + os.pathsep + relaxed_env.get("PATH", "")

        try:
            for index, (name, message, mutates, defer_check) in enumerate(STAGES, 1):
                if args.through is not None and index > args.through:
                    break

                if name == "05_seed_advanced_cleanup_issue_queue.py" and not args.sync_issues:
                    print(f"\n=== {index:02d}/{len(STAGES):02d} SKIP optional issue synchronization ===")
                    completed = index
                    continue

                print(f"\n=== {index:02d}/{len(STAGES):02d} {message} ===")
                env = relaxed_env if defer_check else normal_env
                result = subprocess.run(
                    [sys.executable, str(stage_dir / name)],
                    cwd=repo,
                    env=env,
                )
                if result.returncode:
                    raise RuntimeError(f"stage {index:02d} failed: {name}")

                if mutates:
                    checkpoint(repo, message, original_untracked)
                completed = index

        except Exception as exc:
            failure = exc

        finally:
            if not args.leave_checkpoints:
                collapse(repo, base_head)

    print()
    if failure is not None:
        print("MEGA PATCH STOPPED:", failure, file=sys.stderr)
        print(
            f"Completed through stage {completed:02d}. Successful changes remain as one combined working-tree diff.",
            file=sys.stderr,
        )
        print(
            "Structural mismatch or final validation failed. This is the intended repair state.",
            file=sys.stderr,
        )
        raise SystemExit(1)

    print("MEGA-ULTRA PATCH COMPLETED THROUGH REQUESTED STAGE")
    if args.leave_checkpoints:
        print("Temporary checkpoints were retained by request.")
    else:
        print("Temporary checkpoints were collapsed into ONE combined uncommitted diff.")
    if args.through is None or args.through >= len(STAGES):
        print("Real final compiler validation ran in the final validation tranche.")
    else:
        print("Stopped before the final validation tranche by --through; no final compile claim is made.")


if __name__ == "__main__":
    main()
